from tools.mcptester.mcptester.scenarios.base import BaseScenario, TestCase

class LLMTracingScenario(BaseScenario):
    name = 'llm_tracing'
    description = 'LLM traceability tools'

    def get_test_cases(self) -> list[TestCase]:
        return [TestCase(name='get_llm_requests_basic', tool='get_llm_requests', params={'binder_id': 'binder_001'}, expected={'is_array': True, 'error': False, 'array_length_range': [2, 2], 'all_items_keys': ['id', 'artifact_type', 'created_by']}, description='Get 2 LLM requests for binder_001'), TestCase(name='get_llm_requests_by_persona', tool='get_llm_requests', params={'binder_id': 'binder_001', 'persona': 'Theorist'}, expected={'is_array': True, 'error': False, 'min_length': 1}, description='Get LLM requests by Theorist persona'), TestCase(name='get_llm_requests_by_phase', tool='get_llm_requests', params={'binder_id': 'binder_001', 'phase': 1}, expected={'is_array': True, 'error': False, 'min_length': 1}, description='Get LLM requests from phase 1'), TestCase(name='get_llm_requests_by_prompt_key', tool='get_llm_requests', params={'binder_id': 'binder_001', 'prompt_key': 'hypothesis_generation'}, expected={'is_array': True, 'error': False, 'min_length': 1}, description='Get LLM requests by prompt key'), TestCase(name='get_llm_responses_basic', tool='get_llm_responses', params={'binder_id': 'binder_001'}, expected={'is_array': True, 'error': False, 'array_length_range': [2, 2], 'all_items_keys': ['id', 'artifact_type', 'created_by']}, description='Get 2 LLM responses for binder_001'), TestCase(name='get_llm_responses_by_request', tool='get_llm_responses', params={'binder_id': 'binder_001', 'request_id': 'llmreq_001'}, expected={'is_array': True, 'error': False}, description='Get LLM responses for specific request'), TestCase(name='get_llm_responses_successful', tool='get_llm_responses', params={'binder_id': 'binder_001', 'parse_success': True}, expected={'is_array': True, 'error': False, 'min_length': 1}, description='Get successfully parsed LLM responses'), TestCase(name='get_llm_exchanges_basic', tool='get_llm_exchanges', params={'binder_id': 'binder_001'}, expected={'is_array': True, 'error': False, 'min_length': 1}, description='Get LLM request/response exchanges'), TestCase(name='get_llm_exchanges_by_phase', tool='get_llm_exchanges', params={'binder_id': 'binder_001', 'phase': 1}, expected={'is_array': True, 'error': False, 'min_length': 1}, description='Get LLM exchanges from phase 1'), TestCase(name='get_llm_statistics', tool='get_llm_statistics', params={'binder_id': 'binder_001'}, expected={'json_valid': True, 'error': False}, description='Get LLM usage statistics')]